      booking_uid: a.fields.Booking_UID || `row ${a.id}`, service: String(a.fields.Service || ''), appt_start: a.fields.Start,
    });
  }

  // 2. One follow-up: open leads created `followupAfter` to `lostAfter - 1` days ago, Followup_Sent off, nothing booked.
  const isOpen = (r) => {
    const f = r.fields || {};
    return OPEN.includes(f.Status) && typeof f.Created_At === 'number' && !futureBooked.has(String(r.id));
  };
  const age = (r) => daysAgo(r.fields.Created_At);
  const oldestFirst = (a, b) => a.fields.Created_At - b.fields.Created_At;
  leadRows
    .filter((r) => isOpen(r) && !r.fields.Followup_Sent && age(r) >= followupAfter && age(r) < lostAfter)
    .sort(oldestFirst)
    .slice(0, maxFollowups)
    .forEach((r) => push({
      kind: 'followup', template: 'followup_day2', ...person(String(r.id)),
      flag_table: 'LEADS', flag_row_id: r.id, flag_column: 'Followup_Sent', flag_value: r.fields.Followup_Sent ? 1 : null,
    }));

  // 3. Mark Lost: open leads `lostAfter`+ days old, unless staff have a call-back planned (Next_Action_At in the future).
  if (cfg.mark_lost !== false) {
    leadRows
      .filter((r) => isOpen(r) && age(r) >= lostAfter && !(typeof r.fields.Next_Action_At === 'number' && r.fields.Next_Action_At * 1000 > nowMs))
      .sort(oldestFirst)
      .slice(0, maxLost)
      .forEach((r) => push({ kind: 'lost', ...person(String(r.id)) }));
